164	    process.stderr.write(`perf-regress: ${parseError}\n`);
165	    return EXIT_USAGE;
166	  }
167	
168	  const command = values.command;
169	  const output = values.output;
170	  if (command === undefined || command === '') {
171	    process.stderr.write('perf-regress: --command 不能为空\n');
172	    return EXIT_USAGE;
173	  }
174	  if (output === undefined || output === '') {
175	    process.stderr.write('perf-regress: --output 不能为空\n');
176	    return EXIT_USAGE;
177	  }
178	
179	  const runsR = parsePositiveIntOption(values, 'runs', { min: 1, required: true });
180	  if (runsR.error) {
181	    process.stderr.write(`perf-regress: ${runsR.error}\n`);
182	    return EXIT_USAGE;
183	  }
184	  const warmupR = parsePositiveIntOption(values, 'warmup', { min: 0, required: false });
185	  if (warmupR.error) {
186	    process.stderr.write(`perf-regress: ${warmupR.error}\n`);
187	    return EXIT_USAGE;
188	  }
189	  const timeoutR = parsePositiveIntOption(values, 'timeout-ms', { min: 1, required: true });
190	  if (timeoutR.error) {
191	    process.stderr.write(`perf-regress: ${timeoutR.error}\n`);
192	    return EXIT_USAGE;
193	  }
194	
195	  const runs = runsR.value;
196	  const warmup = warmupR.value === undefined ? 0 : warmupR.value;
197	  const timeoutMs = timeoutR.value;
198	
199	  const samples = [];
200	  const errors = [];
201	
202	  // 先顺序预热：异常记录后继续；但进程无法启动属致命错误（退出码 2，不写 output）。
203	  for (let index = 0; index < warmup; index++) {
204	    let result;
205	    try {
206	      result = await runOnce(command, timeoutMs);
207	    } catch {
208	      reportStartupFailure('warmup', index, null);
209	      return EXIT_USAGE;
210	    }
211	    if (result.reason === 'timeout') {
212	      errors.push({ stage: 'warmup', index, reason: 'timeout', exit_code: null });
213	    } else if (isStartupExitCode(result.exitCode)) {
214	      reportStartupFailure('warmup', index, result.exitCode);
215	      return EXIT_USAGE;
216	    } else if (result.exitCode !== 0) {
217	      errors.push({ stage: 'warmup', index, reason: 'nonzero_exit', exit_code: result.exitCode });
218	    }
219	  }
220	
221	  let fatalSpawn = false;
222	
223	  // 再顺序采集：异常记录后跳过该次；进程无法启动则致命（退出码 2，不写 output）。
224	  for (let index = 0; index < runs; index++) {
225	    let result;
226	    try {
227	      result = await runOnce(command, timeoutMs);
228	    } catch {
229	      reportStartupFailure('measure', index, null);
230	      fatalSpawn = true;
231	      break;
232	    }
233	    if (result.reason === 'timeout') {
234	      errors.push({ stage: 'measure', index, reason: 'timeout', exit_code: null });
235	      continue;
236	    }
237	    if (isStartupExitCode(result.exitCode)) {
238	      reportStartupFailure('measure', index, result.exitCode);
239	      fatalSpawn = true;
240	      break;
241	    }
242	    if (result.exitCode !== 0) {
243	      errors.push({ stage: 'measure', index, reason: 'nonzero_exit', exit_code: result.exitCode });
244	      continue;
245	    }
246	    samples.push({
247	      index,
248	      started_at: result.startedAt.toISOString(),
249	      duration_ns: result.durationNs,
250	      exit_code: result.exitCode,
251	    });
252	  }
253	
254	  if (fatalSpawn) {
255	    return EXIT_USAGE;
256	  }
257	
258	  const summary = samples.length === 0
259	    ? emptySummary()
260	    : computeSummary(samples.map((s) => s.duration_ns));
261	
262	  const report = {
263	    command,
264	    runs,
265	    warmup,
266	    timeout_ms: timeoutMs,
267	    unit: 'ns',
268	    samples,
269	    summary,
270	    errors,
271	  };
272	
273	  let payload;
274	  try {
275	    payload = JSON.stringify(report, null, 2) + '\n';
276	  } catch (err) {
277	    process.stderr.write(`perf-regress: 结果序列化失败: ${err.message}\n`);
278	    return EXIT_OUTPUT_ERROR;
279	  }
