288	  return errors.some((e) => e.stage === 'measure') ? EXIT_MEASURE_ERROR : EXIT_OK;
289	}
290	
291	module.exports = {
292	  collect,
293	  parseArgs,
294	  runOnce,
295	  computeSummary,
296	  EXIT_OK,
297	  EXIT_USAGE,
298	  EXIT_MEASURE_ERROR,
299	  EXIT_OUTPUT_ERROR,
300	};
