17	// 解析有限数值选项；check 为取值范围校验，不满足时返回 describe 描述的错误。
18	function parseNumberOption(values, key, { defaultValue, check, describe }) {
19	  if (!Object.prototype.hasOwnProperty.call(values, key)) {
20	    return { value: defaultValue };
21	  }
22	  const raw = values[key];
23	  const value = Number(raw);
24	  if (raw.trim() === '' || !Number.isFinite(value) || !check(value)) {
25	    return { error: `参数 --${key} 必须${describe}，实际为: ${raw}` };
26	  }
27	  return { value };
28	}
29	
30	// 读取并校验一份 collect JSON，提取 exit_code 为 0 的 duration_ns。
31	// 返回 { command, durations } 或 { error }。
32	async function loadInput(path, label) {
33	  let text;
34	  try {
35	    text = await fs.readFile(path, 'utf8');
36	  } catch (err) {
37	    return { error: `无法读取 ${label} 文件 ${path}: ${err.message}` };
38	  }
39	  let report;
40	  try {
41	    report = JSON.parse(text);
42	  } catch {
43	    return { error: `${label} 文件不是合法 JSON: ${path}` };
44	  }
45	  if (!report || typeof report !== 'object' || Array.isArray(report)) {
46	    return { error: `${label} 文件结构无效: 顶层须为对象` };
47	  }
48	  if (report.unit !== 'ns') {
49	    return { error: `${label} 文件 unit 必须为 "ns"` };
50	  }
51	  if (typeof report.command !== 'string') {
52	    return { error: `${label} 文件缺少有效的 command 字段` };
53	  }
54	  if (!Array.isArray(report.samples)) {
55	    return { error: `${label} 文件 samples 必须为数组` };
56	  }
57	  const durations = [];
58	  for (const sample of report.samples) {
59	    if (!sample || typeof sample !== 'object' || sample.exit_code !== 0) {
60	      continue;
61	    }
62	    if (!Number.isSafeInteger(sample.duration_ns) || sample.duration_ns < 0) {
63	      return { error: `${label} 文件含非法 duration_ns（须为非负安全整数）` };
64	    }
65	    durations.push(sample.duration_ns);
66	  }
67	  if (durations.length < 2) {
68	    return { error: `${label} 有效样本不足 2 个（exit_code 为 0 的样本）` };
69	  }
70	  return { command: report.command, durations };
71	}
72	
73	// 单项指标的候选减基线差：ns 差与百分比。
74	// 基线为 0 时：候选也为 0 则百分比为 0，否则为 null。
75	function metricDelta(base, cand) {
76	  const ns = round6(cand - base);
77	  let percent;
78	  if (base === 0) {
79	    percent = cand === 0 ? 0 : null;
80	  } else {
81	    percent = round6(((cand - base) / base) * 100);
82	  }
83	  return { ns, percent };
84	}
85	
86	// 归因：central_tendency/tail_latency/variability 分别对应 mean/p95/stddev 的百分比。
87	// dominant_factor 取最大正向项，平手按上述顺序；百分比为 null（基线 0 候选非 0）
88	// 视为无穷大正向；无正向值为 none。
89	function buildAttribution(delta) {
90	  const attribution = {
91	    central_tendency_percent: delta.mean.percent,
92	    tail_latency_percent: delta.p95.percent,
93	    variability_percent: delta.stddev.percent,
94	  };
95	  const entries = [
96	    ['central_tendency', attribution.central_tendency_percent],
97	    ['tail_latency', attribution.tail_latency_percent],
98	    ['variability', attribution.variability_percent],
99	  ];
100	  let dominant = null;
101	  let best = 0;
102	  for (const [name, percent] of entries) {
103	    const effective = percent === null ? Infinity : percent;
104	    if (effective > 0 && effective > best) {
105	      best = effective;
106	      dominant = name;
107	    }
108	  }
109	  attribution.dominant_factor = dominant === null ? 'none' : dominant;
110	  return attribution;
111	}
112	
113	// 由两份已通过 loadInput 校验的输入，按 compare 口径重算统计量、Welch 与归因。
114	// decision 不在此给出：compare 以 welch.p_value 判定，compare-suite 以校正后 p 判定。
115	function buildCompareResult(baseline, candidate) {
116	  const baselineSummary = computeSummary(baseline.durations);
117	  const candidateSummary = computeSummary(candidate.durations);
118	
119	  const delta = {
120	    mean: metricDelta(baselineSummary.mean, candidateSummary.mean),
121	    median: metricDelta(baselineSummary.median, candidateSummary.median),
122	    p95: metricDelta(baselineSummary.p95, candidateSummary.p95),
123	    stddev: metricDelta(baselineSummary.stddev, candidateSummary.stddev),
124	  };
125	
126	  const welch = welchTest(baseline.durations, candidate.durations);
127	  const attribution = buildAttribution(delta);
128	  return { baselineSummary, candidateSummary, delta, welch, attribution };
129	}
130	
131	// compare 四类 decision 口径：p_value <= alpha 为显著，再按 mean 百分比与阈值判定。
132	// 基线均值为 0 而候选非 0（percent 为 null）视为达到阈值的增加。
133	function decide(pValue, alpha, meanPercent, minChangePercent) {
134	  if (!(pValue <= alpha)) {
135	    return 'not_significant';
