  return path.join(dir, prefix);
}

function readJson(p) {
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

test('成功采集：退出码 0，顶层字段与 samples/summary 正确', () => {
  const out = withTempFile('ok.json');
