    '--timeout-ms', '5000', '--output', out]);
  assert.equal(r.status, 2);
  assert.equal(fs.readFileSync(out, 'utf8'), 'KEEP-ME');
});

test('进程无法启动（命令不存在，shell 127）：退出码 2，不写 output，按 nonzero_exit 而非 timeout', () => {
