  assert.deepEqual(result.cases[1].errors,
    [{ stage: 'warmup', index: 0, reason: 'timeout', exit_code: null },
      { stage: 'measure', index: 0, reason: 'timeout', exit_code: null }]);
  assert.equal(result.suite_summary.ok, 2);
  assert.equal(result.suite_summary.measure_errors, 0);
  assert.equal(result.suite_summary.sample_count, 0);
  assert.equal(result.suite_summary.error_count, 5);
}, 30000);

